CREATE TABLE community_requests(account_id TEXT NOT NULL REFERENCES accounts(id),request_id TEXT NOT NULL,operation TEXT NOT NULL,digest TEXT NOT NULL,result TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(account_id,request_id));
CREATE TABLE community_bounties(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES accounts(id),title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,tags TEXT NOT NULL,asset_id TEXT NOT NULL,reward_units TEXT NOT NULL,decimals INTEGER NOT NULL,deadline INTEGER NOT NULL,deliverables TEXT NOT NULL,acceptance TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('recruiting','active','ended','cancelled')),partner_id TEXT REFERENCES accounts(id),partner_confirmed INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL DEFAULT '',hidden INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX community_bounties_list ON community_bounties(hidden,created_at,id);
CREATE TABLE community_applications(id TEXT PRIMARY KEY,bounty_id TEXT NOT NULL REFERENCES community_bounties(id),account_id TEXT NOT NULL REFERENCES accounts(id),message TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(bounty_id,account_id));
CREATE TABLE community_deliveries(id TEXT PRIMARY KEY,bounty_id TEXT NOT NULL REFERENCES community_bounties(id),account_id TEXT NOT NULL REFERENCES accounts(id),body TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE community_comments(id TEXT PRIMARY KEY,bounty_id TEXT NOT NULL REFERENCES community_bounties(id),account_id TEXT NOT NULL REFERENCES accounts(id),body TEXT NOT NULL,hidden INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE community_reviews(id TEXT PRIMARY KEY,bounty_id TEXT NOT NULL REFERENCES community_bounties(id),author_id TEXT NOT NULL REFERENCES accounts(id),recipient_id TEXT NOT NULL REFERENCES accounts(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),body TEXT NOT NULL,hidden INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,UNIQUE(bounty_id,author_id));
CREATE TABLE community_providers(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),kind TEXT NOT NULL CHECK(kind IN('business','cloud')),name TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,pricing TEXT NOT NULL,languages TEXT NOT NULL,regions TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','approved','rejected','revoked')),revision INTEGER NOT NULL DEFAULT 1,reason TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(account_id,kind));
CREATE TABLE community_certifications(account_id TEXT NOT NULL REFERENCES accounts(id),kind TEXT NOT NULL CHECK(kind IN('official','business','cloud')),subject TEXT NOT NULL,scope TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('active','revoked')),valid_until INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(account_id,kind));
CREATE TABLE community_reports(id TEXT PRIMARY KEY,reporter_id TEXT NOT NULL REFERENCES accounts(id),target_type TEXT NOT NULL,target_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',resolution TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE community_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,reason TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE community_preferences(account_id TEXT PRIMARY KEY REFERENCES accounts(id),asset_public INTEGER NOT NULL DEFAULT 0,activity_public INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL);
CREATE TABLE community_activity(account_id TEXT PRIMARY KEY REFERENCES accounts(id),last_seen INTEGER NOT NULL,last_activity INTEGER NOT NULL,total_ms INTEGER NOT NULL DEFAULT 0);
CREATE TABLE community_presence(session_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),last_seen INTEGER NOT NULL,last_activity INTEGER NOT NULL,visible INTEGER NOT NULL);
CREATE TABLE community_activity_days(account_id TEXT NOT NULL REFERENCES accounts(id),day TEXT NOT NULL,milliseconds INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(account_id,day));
CREATE TABLE community_level_rules(version INTEGER PRIMARY KEY,thresholds TEXT NOT NULL,idle_ms INTEGER NOT NULL,daily_ms INTEGER NOT NULL,created_at INTEGER NOT NULL);
INSERT INTO community_level_rules VALUES(1,'[0,60,180,480,960,1800]',300000,7200000,0);
CREATE TABLE community_token_applications(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),name TEXT NOT NULL,symbol TEXT NOT NULL,description TEXT NOT NULL,supply_units TEXT NOT NULL,decimals INTEGER NOT NULL,recipient TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','rejected','awaiting_configuration','cancelled')),revision INTEGER NOT NULL DEFAULT 1,review_reason TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
